package com.arcus.alert;
import android.content.Context;
import android.graphics.Canvas;
import android.graphics.Paint;
import android.graphics.Color;
import android.graphics.DashPathEffect;
import android.view.View;
import android.view.MotionEvent;
import android.view.ScaleGestureDetector;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

public class ChartView extends View {
 public static class Candle {public final long time;public final double open,high,low,close,volume;public Candle(long t,double o,double h,double l,double c){this(t,o,h,l,c,0);}public Candle(long t,double o,double h,double l,double c,double v){time=t;open=o;high=h;low=l;close=c;volume=v;}}
 public interface OnPriceTapListener {void onPriceTap(double price);} public interface OnAlertDragListener {void onMoved(int index,double price);void onSelected(int index);} public interface OnChartSwipeListener {void onSwipe(int direction);}
 private final Paint p=new Paint(3);private final ArrayList<Candle> candles=new ArrayList<>();private final ArrayList<Double>alertPrices=new ArrayList<>(); private OnAlertDragListener dragListener; private int draggingIndex=-1; private float alertDownY;
 private OnPriceTapListener listener;private OnChartSwipeListener swipeListener;private double min=0,max=1,selectedPrice=0,verticalScale=1.0;private float crossY=-1,lastX,lastY,downX,panRemainder=0;private boolean edgeSwipe=false;private int visibleCount=90,startIndex=0;private boolean plusDown=false;
 private final ScaleGestureDetector scaleDetector;private static final int RIGHT_GUTTER=64,LEFT_GUTTER=42;private int dp(float v){return (int)(v*getResources().getDisplayMetrics().density);}
 public ChartView(Context c){super(c);setLayerType(View.LAYER_TYPE_SOFTWARE,null);scaleDetector=new ScaleGestureDetector(c,new ScaleGestureDetector.SimpleOnScaleGestureListener(){@Override public boolean onScale(ScaleGestureDetector d){int old=visibleCount;visibleCount=Math.max(12,Math.min(240,(int)(visibleCount/d.getScaleFactor())));if(old!=visibleCount){startIndex=Math.max(0,Math.min(Math.max(0,candles.size()-visibleCount),startIndex));recalcRange();invalidate();}return true;}});}
 public void setOnPriceTapListener(OnPriceTapListener l){listener=l;} public void setOnChartSwipeListener(OnChartSwipeListener l){swipeListener=l;} public void resetView(){visibleCount=90;startIndex=Math.max(0,candles.size()-visibleCount);verticalScale=1.0;crossY=-1;recalcRange();invalidate();} public void setOnAlertDragListener(OnAlertDragListener l){dragListener=l;} public void zoomHorizontal(float factor){int old=visibleCount;visibleCount=Math.max(12,Math.min(240,Math.round(visibleCount*factor)));if(old!=visibleCount){startIndex=Math.max(0,Math.min(Math.max(0,candles.size()-visibleCount),startIndex+(old-visibleCount)/2));recalcRange();invalidate();}} public void zoomVertical(float factor){verticalScale=Math.max(0.35,Math.min(4.0,verticalScale*factor));recalcRange();invalidate();}
 public void setCandles(List<Candle> data){candles.clear();if(data!=null)candles.addAll(data);startIndex=Math.max(0,candles.size()-visibleCount);recalcRange();invalidate();}
 public void setAlertPrices(List<Double> values){alertPrices.clear();if(values!=null)alertPrices.addAll(values);recalcRange();invalidate();}
 private void recalcRange(){double lo=Double.MAX_VALUE,hi=-Double.MAX_VALUE;int end=Math.min(candles.size(),startIndex+visibleCount);for(int i=startIndex;i<end;i++){Candle c=candles.get(i);lo=Math.min(lo,c.low);hi=Math.max(hi,c.high);}for(double v:alertPrices){lo=Math.min(lo,v);hi=Math.max(hi,v);}if(lo==Double.MAX_VALUE){lo=0;hi=1;}if(lo==hi){double v=Math.max(Math.abs(lo)*0.001,0.000001);lo-=v;hi+=v;}double mid=(hi+lo)/2.0,half=(hi-lo)*0.54/verticalScale;min=mid-half;max=mid+half;}
 private float yForPrice(double price){return 18+(float)((max-price)/(max-min))*(getHeight()-36);}
 private double priceAt(float y){float top=18,bottom=getHeight()-18;return max-((Math.max(top,Math.min(bottom,y))-top)/(bottom-top))*(max-min);}
 @Override protected void onDraw(Canvas c){super.onDraw(c);float w=getWidth(),h=getHeight();c.drawColor(Color.rgb(9,15,27));p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1);p.setColor(Color.rgb(34,48,69));for(int i=1;i<5;i++)c.drawLine(0,h*i/5f,w-RIGHT_GUTTER,h*i/5f,p);
 if(candles.isEmpty()){p.setStyle(Paint.Style.FILL);p.setColor(Color.LTGRAY);p.setTextSize(14);c.drawText("No chart data loaded",18,h/2,p);return;}recalcRange();int end=Math.min(candles.size(),startIndex+visibleCount),count=end-startIndex;float left=LEFT_GUTTER,plotW=Math.max(1,w-RIGHT_GUTTER-left),pad=18,usableH=h-2*pad,step=plotW/Math.max(1,count),body=Math.max(1.5f,step*0.64f);double range=max-min;p.setStyle(Paint.Style.FILL);
 for(int j=0;j<count;j++){Candle x=candles.get(startIndex+j);float xx=left+j*step+step/2;float yh=pad+(float)((max-x.high)/range)*usableH,yl=pad+(float)((max-x.low)/range)*usableH,yo=pad+(float)((max-x.open)/range)*usableH,yc=pad+(float)((max-x.close)/range)*usableH;p.setColor(x.close>=x.open?Color.rgb(52,211,153):Color.rgb(248,113,113));p.setStrokeWidth(1.4f);c.drawLine(xx,yh,xx,yl,p);c.drawRect(xx-body/2,Math.min(yo,yc),xx+body/2,Math.max(yo,yc)+1,p);}
 p.setTextSize(10);p.setColor(Color.rgb(151,166,190));c.drawText(String.format(Locale.US,"%.5f",max),5,13,p);c.drawText(String.format(Locale.US,"%.5f",min),5,h-5,p);
 for(double price:alertPrices){float y=yForPrice(price);if(y<10||y>h-10)continue;p.setColor(Color.rgb(74,170,255));p.setStyle(Paint.Style.STROKE);p.setPathEffect(new DashPathEffect(new float[]{5,5},0));c.drawLine(0,y,w-RIGHT_GUTTER,y,p);p.setPathEffect(null);p.setStyle(Paint.Style.FILL);p.setTextSize(9);p.setColor(Color.rgb(74,170,255));c.drawRoundRect(w-RIGHT_GUTTER+2,y-9,w-2,y+9,4,4,p);p.setColor(Color.WHITE);c.drawText(String.format(Locale.US,"%.5f",price),w-RIGHT_GUTTER+5,y+3,p);}
if(crossY>=0){p.setColor(Color.rgb(244,190,80));p.setStrokeWidth(1.2f);p.setStyle(Paint.Style.STROKE);p.setPathEffect(new DashPathEffect(new float[]{8,6},0));c.drawLine(0,crossY,w-RIGHT_GUTTER,crossY,p);p.setPathEffect(null);p.setStyle(Paint.Style.FILL);String value=String.format(Locale.US,"%.6f",selectedPrice);p.setColor(Color.rgb(244,190,80));c.drawRoundRect(w-RIGHT_GUTTER+2,crossY-10,w-2,crossY+10,5,5,p);p.setColor(Color.rgb(12,18,30));p.setTextSize(9);c.drawText(value,w-RIGHT_GUTTER+5,crossY+3,p);float cx=w-30,cy=crossY;p.setColor(Color.rgb(52,211,153));c.drawCircle(cx,cy,14,p);p.setColor(Color.rgb(5,20,25));p.setTextSize(21);p.setFakeBoldText(true);c.drawText("+",cx-6,cy+7,p);p.setFakeBoldText(false);}
 }
 @Override public boolean onTouchEvent(MotionEvent e){getParent().requestDisallowInterceptTouchEvent(true);scaleDetector.onTouchEvent(e);switch(e.getActionMasked()){
 case MotionEvent.ACTION_DOWN:lastX=e.getX();lastY=e.getY();downX=e.getX();edgeSwipe=e.getX()<dp(28)||e.getX()>getWidth()-dp(28);panRemainder=0;draggingIndex=-1;for(int ai=0;ai<alertPrices.size();ai++){if(Math.abs(e.getY()-yForPrice(alertPrices.get(ai)))<16&&e.getX()<getWidth()-RIGHT_GUTTER){draggingIndex=ai;alertDownY=e.getY();break;}}if(draggingIndex>=0)return true;plusDown=crossY>=0&&(e.getX()<LEFT_GUTTER||e.getX()>getWidth()-RIGHT_GUTTER)&&Math.abs(e.getY()-crossY)<26;if(crossY<0){crossY=e.getY();selectedPrice=priceAt(crossY);}invalidate();return true;
 case MotionEvent.ACTION_POINTER_DOWN:plusDown=false;return true;
 case MotionEvent.ACTION_MOVE:if(draggingIndex>=0){crossY=Math.max(18,Math.min(getHeight()-18,e.getY()));selectedPrice=priceAt(crossY);invalidate();return true;}if(e.getPointerCount()==1&&!scaleDetector.isInProgress()){float dx=e.getX()-lastX,dy=e.getY()-lastY;if(Math.abs(dx)>1){float step=(getWidth()-RIGHT_GUTTER-LEFT_GUTTER)/(float)Math.max(1,visibleCount);panRemainder+=-dx/Math.max(1,step);int shift=(int)panRemainder;if(shift!=0){startIndex=Math.max(0,Math.min(Math.max(0,candles.size()-visibleCount),startIndex+shift));panRemainder-=shift;recalcRange();}}crossY=Math.max(18,Math.min(getHeight()-18,e.getY()));selectedPrice=priceAt(crossY);lastX=e.getX();lastY=e.getY();plusDown=false;invalidate();}return true;
 case MotionEvent.ACTION_UP:if(edgeSwipe&&Math.abs(e.getX()-downX)>dp(80)){if(swipeListener!=null)swipeListener.onSwipe(e.getX()<downX?1:-1);edgeSwipe=false;getParent().requestDisallowInterceptTouchEvent(false);return true;}if(draggingIndex>=0){if(Math.abs(e.getY()-alertDownY)<8){if(dragListener!=null)dragListener.onSelected(draggingIndex);}else if(dragListener!=null){dragListener.onMoved(draggingIndex,priceAt(e.getY()));}draggingIndex=-1;return true;}if(plusDown&&listener!=null&&crossY>=0&&(e.getX()<LEFT_GUTTER||e.getX()>getWidth()-RIGHT_GUTTER)&&Math.abs(e.getY()-crossY)<30)listener.onPriceTap(selectedPrice);plusDown=false;performClick();getParent().requestDisallowInterceptTouchEvent(false);return true;
 case MotionEvent.ACTION_CANCEL:edgeSwipe=false;plusDown=false;getParent().requestDisallowInterceptTouchEvent(false);return true;}return true;}
 @Override public boolean performClick(){super.performClick();return true;}
}